import{_ as s,E as o,o as u,c as d,a2 as i,H as t,g as r,e as n}from"./chunks/framework.BuBU3QrY.js";const b=JSON.parse('{"title":"Concurrent Data Structures","description":"From thread-safe queues to concurrent containers, master lock-based concurrent data structure design strategies.","frontmatter":{"title":"Concurrent Data Structures","description":"From thread-safe queues to concurrent containers, master lock-based concurrent data structure design strategies.","translation":{"source":"documents/vol5-concurrency/ch04-concurrent-data-structures/index.md","source_hash":"a14ec2edba40c33ca7c8caec9a8a57ca94344cbcf67f97eac70d264050d5b7d3","translated_at":"2026-05-20T04:41:26.882048+00:00","engine":"anthropic","token_count":202}},"headers":[],"relativePath":"en/vol5-concurrency/ch04-concurrent-data-structures/index.md","filePath":"en/vol5-concurrency/ch04-concurrent-data-structures/index.md","lastUpdated":null}'),l={name:"en/vol5-concurrency/ch04-concurrent-data-structures/index.md"};function h(f,e,p,m,g,_){const a=o("ChapterLink"),c=o("ChapterNav");return u(),d("div",null,[e[4]||(e[4]=i('<h1 id="concurrent-data-structures" tabindex="-1">Concurrent Data Structures <a class="header-anchor" href="#concurrent-data-structures" aria-label="Permalink to &quot;Concurrent Data Structures&quot;">​</a></h1><p>In the previous two chapters, we covered synchronization primitives (<code>mutex</code>, <code>condition_variable</code>, <code>shared_mutex</code>) and atomic operations (<code>atomic</code>, memory order). Now it is time to put these tools to use — in this chapter, we focus on the design and implementation of concurrent data structures. Concurrent data structures are core components of multithreaded programs: task queues in thread pools, routing caches in servers, and buffers in messaging systems all rely on thread-safe data structures behind the scenes.</p><p>We start with the most practical thread-safe queue — it is the cornerstone of the producer-consumer pattern and the best case study for understanding &quot;how to build correct concurrent components using <code>mutex</code> + <code>condition_variable</code>.&quot; We then expand to more general concurrent container design, discussing the design and trade-offs of four strategies: coarse-grained locking, fine-grained locking, sharded locking, and copy-on-write. Finally, we enter the realm of lock-free programming — from CAS loops and the ABA problem to SPSC ring buffers and the Michael-Scott MPMC queue, building our ability to design and evaluate lock-free concurrent data structures.</p><h2 id="chapter-contents" tabindex="-1">Chapter Contents <a class="header-anchor" href="#chapter-contents" aria-label="Permalink to &quot;Chapter Contents&quot;">​</a></h2>',4)),t(c,{variant:"sub"},{default:r(()=>[t(a,{href:"01-thread-safe-queue"},{default:r(()=>[...e[0]||(e[0]=[n("Thread-Safe Queue",-1)])]),_:1}),t(a,{href:"02-thread-safe-containers"},{default:r(()=>[...e[1]||(e[1]=[n("Thread-Safe Container Design",-1)])]),_:1}),t(a,{href:"03-lock-free-basics"},{default:r(()=>[...e[2]||(e[2]=[n("Lock-Free Programming Basics",-1)])]),_:1}),t(a,{href:"04-lock-free-queues"},{default:r(()=>[...e[3]||(e[3]=[n("SPSC and MPMC Queues",-1)])]),_:1})]),_:1})])}const k=s(l,[["render",h]]);export{b as __pageData,k as default};
